function presetState(preset='blank',username='',displayName=''){
  const next=defaultState();
  next.username=username;
  next.account=displayName||username||'Novo personagem';
  next.total=33;
  next.profileSetupPending=true;
  next.lastSync=null;
  next.quests={items:[],lastSync:null,source:''};
  next.history=[{id:id('event'),type:'milestone',title:'Jornada criada',detail:`Preset ${preset==='iron'?'Ironman':preset==='pvm'?'PvM':preset==='main'?'Main':'personalizado'} iniciado.`,date:new Date().toISOString()}];
  next.skills=skillSeed.map(([name,,target])=>({name,current:name==='Hitpoints'?10:1,target:preset==='pvm'?target:Math.min(target,70),xp:0}));
  if(preset==='iron'){
    next.eras=[['iron-1','Fundamentos e transporte','Teleports, ferramentas e qualidade de vida.'],['iron-2','Questing e desbloqueios','Quests estruturais e acesso a novas regiões.'],['iron-3','Supplies e skilling','Autossuficiência, recursos e produção.'],['iron-4','Slayer e upgrades','Equipamentos e desbloqueios de combate.'],['iron-5','Preparação para PvM','Gear, níveis e primeiras campanhas.'],['iron-6','Raids e endgame','Raids, megarares e objetivos finais.']].map((row,order)=>({id:row[0],title:row[1],description:row[2],order}));
    next.goals=[];next.tasks=[];next.dashboard.focus=[];next.dashboard.upcoming=[];next.bosses.selected=['barrows','dagannoth-rex','gauntlet','corrupted-gauntlet','zulrah','vorkath'];
  }else if(preset==='pvm'){
    next.eras=[['pvm-1','Preparação','Níveis, quests e equipamentos essenciais.'],['pvm-2','Primeiros KCs','Aprender mecânicas e ganhar consistência.'],['pvm-3','Bossing avançado','Projetos, upgrades e combat achievements.'],['pvm-4','Raids','Progressão de invocation e domínio.']].map((row,order)=>({id:row[0],title:row[1],description:row[2],order}));
    next.goals=[];next.tasks=[];next.dashboard.focus=[];next.dashboard.upcoming=[];
  }else if(preset==='blank'){
    next.eras=[{id:'custom-1',title:'Minha jornada',description:'Um capítulo livre para começar.',order:0}];next.goals=[];next.tasks=[];next.dashboard.focus=[];next.dashboard.upcoming=[];next.bosses.selected=[];next.raids.selected=[];
  }
  return next;
}

function loadProfileHub(initialState){
  try{
    const saved=JSON.parse(localStorage.getItem(PROFILES_KEY)||'null');
    if(saved?.version===1&&Array.isArray(saved.profiles)&&saved.profiles.length){saved.profiles.forEach(profile=>profile.state=mergeDefaults(profile.state||presetState(profile.preset,profile.username,profile.name)));if(!saved.profiles.some(profile=>profile.id===saved.activeId))saved.activeId=saved.profiles[0].id;return saved}
  }catch{}
  const mainName=initialState.account&&initialState.account!=='Minha conta'?initialState.account:(initialState.username||'samurai_jao');initialState.account=mainName;
  const main={id:'profile-samurai-jao',name:mainName,username:initialState.username||'samurai_jao',accountType:'main',preset:'main',createdAt:new Date().toISOString(),state:mergeDefaults(initialState)};
  const iron={id:'profile-iron-samuka',name:'Iron Samuka',username:'Iron Samuka',accountType:'ironman',preset:'iron',createdAt:new Date().toISOString(),state:presetState('iron','Iron Samuka','Iron Samuka')};
  const created={version:1,activeId:main.id,profiles:[main,iron]};
  try{localStorage.setItem(PROFILES_KEY,JSON.stringify(created))}catch{}
  return created;
}

function migrate() {
  const saved = JSON.parse(localStorage.getItem(STORE_KEY) || 'null');
  if (saved?.version === 3) return mergeDefaults(saved);
  const next = defaultState();
  const old = JSON.parse(localStorage.getItem(OLD_KEY) || 'null');
  const oldTasks = JSON.parse(localStorage.getItem(TODO_KEY) || 'null');
  if (!old) return next;
  next.account = old.account || next.account; next.username = old.username || next.username; next.total = old.total || next.total; next.totalGoal = old.totalGoal || next.totalGoal; next.lastSync = old.lastSync || null;
  if (old.skills?.length) next.skills = skillSeed.map(([name,current,target]) => { const found = old.skills.find(skill => skill[0] === name); return {name,current:Number(found?.[1] ?? current),target:Number(found?.[2] ?? target),xp:0}; });
  if (old.eras?.length) next.eras = old.eras.map((era,index)=>({id:`era-${index+1}`,title:era[1],description:era[2],order:index}));
  if (old.goals?.length) { next.goals = old.goals.map((goal,index)=>{const matchedSkill=skillSeed.find(([name])=>goal.name.toLowerCase().includes(name.toLowerCase()));const numbers=goal.name.match(/\d+/g)||[];return {id:`legacy-goal-${index}`,title:goal.name,description:goal.desc||'',type:matchedSkill?'skill':'manual',status:normalizeStatus(goal.status),mode:matchedSkill?'skill':'manual',skill:matchedSkill?.[0]||null,target:matchedSkill?Number(numbers.at(-1))||matchedSkill[2]:100,progress:clamp(goal.progress),eraId:goal.era?`era-${goal.era}`:null,priority:index+1}}); const findGoal=name=>next.goals.find(goal=>goal.title===name)?.id; next.dashboard.focus=[old.macro?.name,old.project?.name,old.today?.name].map(findGoal).filter(Boolean); next.dashboard.upcoming=(old.upcoming||[]).map(findGoal).filter(Boolean); }
  if (Array.isArray(oldTasks)) next.tasks = oldTasks.map(task=>({id:id('task'),text:task.text,done:!!task.done,goalId:null}));
  if (old.bosses?.length) { next.bosses.selected=[]; old.bosses.forEach(([name,kc])=>{ let item=next.bosses.catalog.find(b=>b.name===name); if(!item){item={id:`custom-${slug(name)}`,name,category:'Personalizado',wiki:name};next.bosses.catalog.push(item)} next.bosses.selected.push(item.id); next.bosses.progress[item.id]={kc:Number(kc)||0,target:old.pvmDetails?.[name]?.target||25,status:old.pvmDetails?.[name]?.state||'Nunca tentei',best:old.pvmDetails?.[name]?.best||'',gear:old.pvmDetails?.[name]?.gear||'',notes:old.pvmDetails?.[name]?.notes||'',liked:!!old.pvmDetails?.[name]?.liked,project:!!old.pvmDetails?.[name]?.project,image:old.pvmDetails?.[name]?.image||''}; }); }
  return next;
}
function mergeDefaults(saved) { const base=defaultState(),background=saved.preferences?.background==='slideshow'?'wallpaper':saved.preferences?.background; return {...base,...saved,dashboard:{...base.dashboard,...saved.dashboard},quests:{...base.quests,...saved.quests},bosses:{...base.bosses,...saved.bosses},raids:{...base.raids,...saved.raids,items:{...base.raids.items,...saved.raids?.items}},preferences:{...base.preferences,...saved.preferences,background:background||base.preferences.background}}; }
function normalizeStatus(value='') { const v=value.toLowerCase(); return v.includes('concl')?'done':v.includes('andamento')?'active':v.includes('paus')?'paused':'planned'; }
const migratedState=migrate();
let profileHub=loadProfileHub(migratedState);
function activeProfile(){return profileHub.profiles.find(profile=>profile.id===profileHub.activeId)||profileHub.profiles[0]}
let state=mergeDefaults(activeProfile().state);
let route = location.hash.slice(1) || state.preferences.startPage || 'dashboard';
if(route==='skills')route='character';
if(!['dashboard','profiles','roadmap','goals','quests','session','character','pvm','history','customize','settings'].includes(route))route='dashboard';
let ui = {drawer:null,menu:false,goalFilter:'all',goalSearch:'',questFilter:'missing',questSearch:'',questSyncing:false,historyFilter:'all',bossSearch:'',bossCategory:'all',bossManager:false,raidManager:false,customize:false,routeEntering:true,musicIndex:Number(state.preferences.musicTrack)||0,musicPlaying:false,drawerDrafts:{},skipDrawerDraft:false};
let undoState = null;

function persistProfiles(){const profile=activeProfile();if(profile){profile.state=state;profile.name=state.account;profile.username=state.username}localStorage.setItem(PROFILES_KEY,JSON.stringify(profileHub))}
function save(message='Salvo', option=false) { try{persistProfiles()}catch{toast('O armazenamento ficou cheio. Remova alguma imagem personalizada.');return false} applyPreferences(); if(option!==true) toast(message,typeof option==='string'?option:''); return true; }
function toast(message, action='') { const element=$('#toast'); element.innerHTML=`<span>${esc(message)}</span>${action?`<button data-undo>${esc(action)}</button>`:''}`; element.classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>element.classList.remove('show'),2600); }
function snapshotForUndo() { undoState=JSON.stringify(state); }
function undo() { if(!undoState)return; state=JSON.parse(undoState); undoState=null; save('Ação desfeita'); render(); }
function addHistory(type,title,detail='') { state.history.unshift({id:id('event'),type,title,detail,date:new Date().toISOString()}); state.history=state.history.slice(0,250); }
function skill(name) { return state.skills.find(item=>item.name===name); }
function questByName(name){return state.quests.items.find(item=>item.name===name)}
function questProgress(name){const value=Number(questByName(name)?.state);return value===2?100:value===1?50:0}
function questStateLabel(value){return ({0:'Não iniciada',1:'Em andamento',2:'Concluída'})[Number(value)]||'Não sincronizada'}
function goalProgress(goal) { if(goal.mode==='quest')return questProgress(goal.questName); if(goal.mode==='skill'){const current=skill(goal.skill)?.current||0;return clamp((current/Math.max(1,goal.target))*100)} if(goal.mode==='boss'){const current=state.bosses.progress[goal.bossId]?.kc||0;return clamp((current/Math.max(1,goal.target))*100)} if(goal.mode==='raid'){const current=state.raids.items[goal.raidId]?.current||0;return clamp((current/Math.max(1,goal.target))*100)} return clamp(goal.progress); }
function goalById(goalId){return state.goals.find(goal=>goal.id===goalId)}
function statusLabel(status){return ({new:'Nunca tentei',planned:'Planejada',active:'Em andamento',paused:'Pausada',done:'Concluída',archived:'Arquivada'})[status]||status}
function statusClass(status){return `status-${['new','planned','active','paused','done','archived'].includes(status)?status:'planned'}`}
function typeLabel(type){return ({manual:'Meta livre',skill:'Skill',quest:'Quest',boss:'Boss',raid:'Raid',unlock:'Desbloqueio'})[type]||type}
function accountTypeLabel(type){return ({main:'Main',ironman:'Ironman',hardcore:'Hardcore Ironman',ultimate:'Ultimate Ironman',group:'Group Ironman',skiller:'Skiller'})[type]||'Personagem'}

const navItems=[['dashboard','⌂','Visão geral'],['profiles','♟','Personagens'],['roadmap','◈','Roadmap'],['goals','✓','Metas'],['quests','📜','Quests'],['session','◷','Sessão de hoje'],['character','♜','Meu personagem'],['pvm','⚔','Passaporte PvM'],['history','▤','Histórico'],['customize','✦','Personalizar'],['settings','⚙','Configurações']];
const titles={dashboard:['PAINEL DA JORNADA','Visão geral'],profiles:['SALÃO DOS AVENTUREIROS','Personagens'],roadmap:['PROGRESSÃO MACRO','Roadmap'],goals:['CENTRAL DE OBJETIVOS','Metas'],quests:['DIÁRIO DE AVENTURAS','Quests'],session:['PLANEJAMENTO LEVE','Sessão de hoje'],character:['WISE OLD MAN + METAS','Meu personagem'],pvm:['APRENDIZADO E DOMÍNIO','Passaporte PvM'],history:['MEMÓRIA DA CONTA','Histórico'],customize:['SEU PAINEL, SUAS REGRAS','Personalizar'],settings:['DADOS E SINCRONIZAÇÃO','Configurações']};

function appShell(content){const [kicker,title]=titles[route]||titles.dashboard,track=osrsTracks[ui.musicIndex%osrsTracks.length];return `<div class="app-shell ${state.preferences.sidebarCompact?'sidebar-compact':''}"><div class="mobile-backdrop ${ui.menu?'show':''}" data-close-menu></div><aside class="sidebar ${ui.menu?'open':''}"><div class="brand"><span class="brand-crest"><img src="assets/osrs-favicon.png" alt=""></span><div><strong>OSRS</strong><span>Diário da Main</span></div></div><button class="account-card account-switch" data-route="profiles" aria-label="Trocar personagem"><span class="eyebrow">${accountTypeLabel(activeProfile().accountType)}</span><strong>${esc(state.account)}</strong><small>${esc(state.username)} · ${state.total} total</small><span class="account-status"><i class="sync-dot ${state.lastSync?'online':''}"></i>${state.lastSync?'Wise Old Man sincronizado':'Aguardando sincronização'}<b>Trocar ↔</b></span></button><nav aria-label="Navegação principal">${navItems.map(([key,icon,label])=>`<button class="nav-item ${route===key?'active':''}" data-route="${key}" ${route===key?'aria-current="page"':''}><span>${icon}</span><b>${label}</b></button>`).join('')}</nav><div class="sidebar-foot"><span>● progresso salvo neste dispositivo</span></div></aside><main class="main"><header class="topbar"><button class="icon-btn mobile-only" data-menu aria-label="Abrir menu">☰</button><button class="icon-btn home-rune" data-route="dashboard" aria-label="Voltar para a visão geral">⌂</button><div class="page-title"><span class="eyebrow">${kicker}</span><h1>${title}</h1></div><div class="top-actions"><div class="music-player ${ui.musicPlaying?'playing':''}" title="Trilha sonora de Gielinor"><button data-music-prev aria-label="Faixa anterior">‹</button><span class="music-note" aria-hidden="true">♫</span><span class="music-copy"><small>TOCANDO AGORA</small><b data-music-label>${esc(track.name)}</b><em data-music-area>${esc(track.area)}</em></span><button data-music-toggle aria-label="${ui.musicPlaying?'Pausar música':'Tocar música'}">${ui.musicPlaying?'Ⅱ':'▶'}</button><button data-music-next aria-label="Próxima faixa">›</button><label class="music-volume" title="Volume"><span>▰</span><input data-music-volume type="range" min="0" max="100" value="${state.preferences.musicVolume}" aria-label="Volume da música"></label></div><span class="top-total"><small>TOTAL LEVEL</small><strong>${state.total}</strong></span><span class="sync-dot ${state.lastSync?'online':''}" title="${state.lastSync?`Atualizado ${esc(state.lastSync)}`:'Ainda não sincronizado'}"></span><button class="ghost-btn" data-focus>◉ <span>Modo foco</span></button></div></header><div id="content" class="${ui.routeEntering?'page-enter':''}">${content}</div></main></div>${ui.drawer?drawer():''}`}
function navigate(next){const current=location.hash.slice(1)||state.preferences.startPage||'dashboard';ui.drawer=null;ui.menu=false;ui.routeEntering=true;route=next;window.scrollTo({top:0,behavior:'instant'});if(current!==next)location.hash=next;render()}
async function activateProfile(profileId){const target=profileHub.profiles.find(profile=>profile.id===profileId);if(!target||target.id===profileHub.activeId)return;activeProfile().state=state;profileHub.activeId=target.id;state=mergeDefaults(target.state);ui.goalFilter='all';ui.goalSearch='';ui.questFilter='missing';ui.questSearch='';ui.historyFilter='all';ui.bossSearch='';ui.bossCategory='all';ui.drawer=null;ui.musicIndex=Number(state.preferences.musicTrack)||0;persistProfiles();navigate('dashboard');toast(`${target.name} selecionado`);if(!state.lastSync)await syncAccount();if(!state.quests.lastSync)await syncQuests(true)}
function sectionHead(kicker,title,actions=''){return `<div class="section-head"><div>${kicker?`<span class="eyebrow">${kicker}</span>`:''}<h2>${title}</h2></div>${actions}</div>`}
function progressBar(value,label=''){return `<div class="progress-wrap"><div class="progress"><i style="width:${clamp(value)}%"></i></div>${label?`<span>${esc(label)}</span>`:''}</div>`}
function emptyState(icon,title,text,action=''){return `<div class="empty"><span>${icon}</span><strong>${title}</strong><p>${text}</p>${action}</div>`}
function goalCard(goal,compact=false){const progress=Math.round(goalProgress(goal));const controls=!compact&&goal.mode==='manual'?`<div class="quick-progress"><button data-goal-progress="${goal.id}:25">25%</button><button data-goal-progress="${goal.id}:50">50%</button><button data-goal-progress="${goal.id}:75">75%</button><button class="complete-btn" data-goal-progress="${goal.id}:100">✓ Concluir</button></div>`:!compact?'<div class="auto-progress">↻ progresso automático</div>':'';return `<article class="goal-card card ${statusClass(goal.status)} ${compact?'compact':''}" data-goal-card="${goal.id}"><div class="card-top"><div class="goal-labels"><span class="tag">${typeLabel(goal.type)}</span><span class="status-pill">${statusLabel(goal.status)}</span></div><button class="more-btn" data-goal-menu="${goal.id}" aria-label="Ações de ${esc(goal.title)}">•••</button></div><h3>${esc(goal.title)}</h3><p>${esc(goal.description||'Sem descrição.')}</p>${progressBar(progress)}<div class="meta-row"><span>${statusLabel(goal.status)}</span><strong>${progress}%</strong></div>${controls}</article>`}
function widgetMoveControls(key){const widgets=state.dashboard.widgets,index=widgets.indexOf(key);return `<div class="widget-actions"><button data-widget-up="${key}" ${index===0?'disabled':''}>↑</button><button data-widget-down="${key}" ${index===widgets.length-1?'disabled':''}>↓</button><button data-widget-hide="${key}" aria-label="Ocultar painel">×</button></div>`}

function dashboardPage(){const widgets={today:widgetToday,journey:widgetJourney,focus:widgetFocus,upcoming:widgetUpcoming,character:widgetCharacter,recent:widgetRecent};return `<div class="dashboard-toolbar"><div><strong>Bem-vindo, ${esc(state.account)}</strong><span>${state.lastSync?`Conta atualizada em ${esc(state.lastSync)}`:'Sincronize sua conta para atualizar os níveis.'}</span></div><button class="ghost-btn" data-toggle-dashboard-edit>${ui.customize?'Concluir organização':'⚙ Organizar painel'}</button></div><div class="dashboard-grid">${state.dashboard.widgets.filter(key=>!state.dashboard.hidden.includes(key)).map(key=>`<section class="widget widget-${key}">${ui.customize?widgetMoveControls(key):''}${widgets[key]()}</section>`).join('')}</div>`}
function widgetToday(){const done=state.tasks.filter(t=>t.done).length;return `${sectionHead('SESSÃO DE HOJE',`Ações leves <span class="count">${done}/${state.tasks.length}</span>`,`<button class="text-btn" data-route="session">Configurar →</button>`)}<div class="today-list">${state.tasks.slice(0,4).map(task=>`<label class="today-item ${task.done?'done':''}"><input type="checkbox" data-task-check="${task.id}" ${task.done?'checked':''}><span>${esc(task.text)}</span></label>`).join('')||'<span class="muted">Nenhuma ação para hoje.</span>'}</div>`}
function widgetJourney(){const current=state.eras.find(era=>state.goals.some(goal=>goal.eraId===era.id&&goal.status==='active'))||state.eras[0];const goals=state.goals.filter(goal=>goal.eraId===current.id);const value=goals.length?Math.round(goals.reduce((sum,goal)=>sum+goalProgress(goal),0)/goals.length):0;return `${sectionHead('ERA ATUAL',esc(current.title),`<button class="text-btn" data-route="roadmap">Abrir roadmap →</button>`)}<p>${esc(current.description)}</p>${progressBar(value)}<div class="meta-row"><span>${goals.length} metas vinculadas</span><strong>${value}%</strong></div>`}
function widgetFocus(){const goals=state.dashboard.focus.map(goalById).filter(Boolean);return `${sectionHead('FOCO ATUAL','O que importa agora',`<button class="text-btn" data-dashboard-focus>Escolher metas →</button>`)}<div class="focus-grid">${goals.map(goal=>goalCard(goal,true)).join('')||emptyState('✦','Sem foco definido','Escolha até três metas importantes.')}</div>`}
function widgetUpcoming(){const goals=state.dashboard.upcoming.map(goalById).filter(Boolean);return `${sectionHead('PRÓXIMOS DESBLOQUEIOS','No horizonte',`<button class="text-btn" data-dashboard-focus>Editar ordem →</button>`)}<div class="unlock-list">${goals.map((goal,index)=>`<button class="${statusClass(goal.status)}" data-goal-open="${goal.id}"><span>${goal.status==='done'?'✓':index+1}</span><div><strong>${esc(goal.title)}</strong><small>${Math.round(goalProgress(goal))}% · ${statusLabel(goal.status)}</small></div><b>→</b></button>`).join('')||'<span class="muted">Nenhum desbloqueio escolhido.</span>'}</div>`}
function widgetCharacter(){const closest=state.skills.filter(s=>s.target>s.current).sort((a,b)=>(a.target-a.current)-(b.target-b.current)).slice(0,4);return `${sectionHead('PERSONAGEM',`${state.total} total`,`<button class="text-btn" data-route="character">Ver todas →</button>`)}<div class="mini-skills">${closest.map(item=>`<div><img src="assets/${item.name.toLowerCase()}-icon.png" alt=""><span><strong>${item.name}</strong><small>${item.current} / ${item.target}</small></span>${progressBar(item.current/item.target*100)}</div>`).join('')}</div>`}
function widgetRecent(){const events=state.history.slice(0,4);return `${sectionHead('ÚLTIMAS CONQUISTAS','Sua jornada',`<button class="text-btn" data-route="history">Histórico →</button>`)}<div class="recent-list">${events.map(event=>`<div><span class="event-icon">${event.type==='sync'?'↻':event.type==='goal'?'✓':'✦'}</span><div><strong>${esc(event.title)}</strong><small>${formatDate(event.date)} · ${esc(event.detail)}</small></div></div>`).join('')}</div>`}

function profilesPage(){activeProfile().state=state;return `${sectionHead('TODAS AS CONTAS','Escolha sua aventura',`<button class="primary-btn" data-profile-new>+ Novo personagem</button>`)}<p class="page-intro">Cada personagem tem dados, Roadmap, metas, quests, sessão e PvM independentes. Os presets são apenas pontos de partida e continuam totalmente editáveis.</p><div class="profiles-grid">${profileHub.profiles.map(profile=>{const data=profile.id===profileHub.activeId?state:mergeDefaults(profile.state),active=profile.id===profileHub.activeId,questDone=(data.quests?.items||[]).filter(item=>Number(item.state)===2).length,goalDone=(data.goals||[]).filter(goal=>goal.status==='done').length;return `<article class="profile-card card ${active?'active':''}"><div class="profile-banner"><span>${profile.accountType==='ironman'?'⚒':profile.accountType==='hardcore'?'☠':profile.accountType==='ultimate'?'◆':'♜'}</span><div><small>${accountTypeLabel(profile.accountType)} · preset ${profile.preset}</small><h2>${esc(profile.name)}</h2><p>${esc(profile.username)}</p></div>${active?'<b class="pill">Em uso</b>':''}</div><div class="profile-stats"><span><small>Total level</small><strong>${data.total||'—'}</strong></span><span><small>Quests concluídas</small><strong>${questDone||'—'}</strong></span><span><small>Metas concluídas</small><strong>${goalDone}</strong></span><span><small>Último sync</small><strong>${data.lastSync?formatDate(data.lastSync):'Nunca'}</strong></span></div><div class="profile-actions"><button class="primary-btn" data-profile-switch="${profile.id}" ${active?'disabled':''}>${active?'Personagem atual':'Entrar neste personagem'}</button><button class="ghost-btn" data-profile-edit="${profile.id}">Editar</button>${profileHub.profiles.length>1?`<button class="ghost-btn danger" data-profile-delete="${profile.id}">Excluir</button>`:''}</div></article>`}).join('')}</div><section class="preset-explainer card"><span class="eyebrow">PRESETS DISPONÍVEIS</span><div><article><strong>♜ Main</strong><p>Jornada geral, quests, diaries e PvM.</p></article><article><strong>⚒ Ironman</strong><p>Autossuficiência, supplies, upgrades e desbloqueios.</p></article><article><strong>⚔ PvM</strong><p>Preparação, KCs, bosses e raids.</p></article><article><strong>✦ Personalizado</strong><p>Um capítulo vazio para montar livremente.</p></article></div></section>`}

function roadmapPage(){const eras=[...state.eras].sort((a,b)=>a.order-b.order);return `${sectionHead('MAPA DA PROGRESSÃO','O caminho da sua main',`<button class="primary-btn" data-era-new>+ Nova era</button>`)}<p class="page-intro">As metas calculam o progresso de cada capítulo. Reordene, edite e construa sua jornada do seu jeito.</p><div class="roadmap">${eras.map((era,index)=>{const goals=state.goals.filter(goal=>goal.eraId===era.id&&goal.status!=='archived');const value=goals.length?Math.round(goals.reduce((sum,goal)=>sum+goalProgress(goal),0)/goals.length):0;return `<article class="era-card card"><div class="era-rail"><span>${index+1}</span><i></i></div><div class="era-content"><div class="card-top"><span class="eyebrow">CAPÍTULO ${index+1}${goals.some(goal=>goal.status==='active')?' · EM ANDAMENTO':''}</span><div class="inline-actions"><button data-era-up="${era.id}" ${index===0?'disabled':''}>↑</button><button data-era-down="${era.id}" ${index===eras.length-1?'disabled':''}>↓</button><button data-era-edit="${era.id}">Editar</button></div></div><h2>${esc(era.title)}</h2><p>${esc(era.description)}</p>${progressBar(value)}<div class="meta-row"><span>${goals.length} metas</span><strong>${value}%</strong></div><div class="era-goals">${goals.sort((a,b)=>a.priority-b.priority).map(goal=>`<button class="${statusClass(goal.status)}" data-goal-open="${goal.id}"><span>${goal.status==='done'?'✓':'○'}</span><strong>${esc(goal.title)}</strong><small>${statusLabel(goal.status)} · ${Math.round(goalProgress(goal))}%</small></button>`).join('')||'<span class="muted">Nenhuma meta vinculada.</span>'}</div><button class="ghost-btn small" data-goal-new-era="${era.id}">+ Adicionar meta neste capítulo</button></div></article>`}).join('')}</div>`}

function goalsPage(){const visible=state.goals.filter(goal=>ui.goalFilter==='archived'?goal.status==='archived':goal.status!=='archived').filter(goal=>ui.goalFilter==='all'||ui.goalFilter==='archived'||goal.status===ui.goalFilter).filter(goal=>(goal.title+' '+goal.description).toLowerCase().includes(ui.goalSearch.toLowerCase())).sort((a,b)=>a.priority-b.priority);return `${sectionHead('CENTRAL DE OBJETIVOS','Metas que movem sua conta',`<button class="primary-btn" data-goal-new>+ Nova meta</button>`)}<div class="filterbar"><label class="search"><span>⌕</span><input data-goal-search value="${esc(ui.goalSearch)}" placeholder="Pesquisar metas..."></label><select data-goal-filter><option value="all">Todos os status</option>${['active','planned','paused','done','archived'].map(status=>`<option value="${status}" ${ui.goalFilter===status?'selected':''}>${statusLabel(status)}</option>`).join('')}</select><span>${visible.length} metas</span></div><div class="goals-grid">${visible.map(goal=>goalCard(goal)).join('')||emptyState('✓','Nenhuma meta encontrada','Mude os filtros ou crie uma nova meta.',`<button class="primary-btn" data-goal-new>Criar meta</button>`)}</div>`}

function questsPage(){const items=state.quests.items||[],counts={missing:items.filter(item=>Number(item.state)!==2).length,active:items.filter(item=>Number(item.state)===1).length,done:items.filter(item=>Number(item.state)===2).length};const visible=items.filter(item=>{const value=Number(item.state);if(ui.questFilter==='missing')return value!==2;if(ui.questFilter==='not-started')return value===0;if(ui.questFilter==='active')return value===1;if(ui.questFilter==='done')return value===2;if(ui.questFilter==='roadmap')return state.goals.some(goal=>goal.mode==='quest'&&goal.questName===item.name&&goal.status!=='archived');return true}).filter(item=>item.name.toLowerCase().includes(ui.questSearch.toLowerCase())).sort((a,b)=>Number(a.state)-Number(b.state)||a.name.localeCompare(b.name));return `${sectionHead('WIKISYNC + ROADMAP','Livro de quests',`<button class="primary-btn" data-quest-sync ${ui.questSyncing?'disabled':''}>${ui.questSyncing?'↻ Atualizando...':'↻ Atualizar quests'}</button>`)}<p class="page-intro">Escolha uma quest faltante e transforme-a em meta. No formulário você decide em qual capítulo do Roadmap ela entra.</p><div class="quest-summary"><div><span>Faltantes</span><strong>${counts.missing}</strong></div><div><span>Em andamento</span><strong>${counts.active}</strong></div><div><span>Concluídas</span><strong>${counts.done}</strong></div><div><span>Último WikiSync</span><strong>${state.quests.lastSync?formatDate(state.quests.lastSync):'—'}</strong><small>${esc(state.quests.source||'')}</small></div></div><div class="filterbar quest-filterbar"><label class="search"><span>⌕</span><input data-quest-search value="${esc(ui.questSearch)}" placeholder="Pesquisar quest..."></label><select data-quest-filter><option value="missing" ${ui.questFilter==='missing'?'selected':''}>Todas as faltantes</option><option value="not-started" ${ui.questFilter==='not-started'?'selected':''}>Não iniciadas</option><option value="active" ${ui.questFilter==='active'?'selected':''}>Em andamento</option><option value="done" ${ui.questFilter==='done'?'selected':''}>Concluídas</option><option value="roadmap" ${ui.questFilter==='roadmap'?'selected':''}>No meu Roadmap</option><option value="all" ${ui.questFilter==='all'?'selected':''}>Todas</option></select><span>${visible.length} quests</span></div><div class="quest-grid">${visible.map(item=>{const linked=state.goals.find(goal=>goal.mode==='quest'&&goal.questName===item.name&&goal.status!=='archived'),era=linked&&state.eras.find(entry=>entry.id===linked.eraId),value=questProgress(item.name);return `<article class="quest-card card quest-state-${Number(item.state)} ${linked?'linked':''}"><div class="quest-card-head"><span class="quest-scroll" aria-hidden="true">📜</span><div><small>${questStateLabel(item.state)}</small><h3>${esc(item.name)}</h3></div><span class="pill">${value}%</span></div>${progressBar(value)}<div class="quest-card-meta"><span>${linked?`Roadmap: ${esc(era?.title||'sem capítulo')}`:'Ainda fora do Roadmap'}</span><a href="https://oldschool.runescape.wiki/w/${encodeURIComponent(item.name.replace(/ /g,'_'))}" target="_blank" rel="noopener">Abrir guia ↗</a></div><button class="${linked?'ghost-btn':'primary-btn'} quest-roadmap-btn" data-quest-goal="${esc(item.name)}">${linked?'✎ Editar meta no Roadmap':'+ Adicionar ao Roadmap'}</button></article>`}).join('')||(state.quests.lastSync?emptyState('📜','Nenhuma quest encontrada','Tente outro filtro ou termo de busca.'):emptyState('📜','Sincronize seu diário','Clique em “Atualizar quests” para carregar o WikiSync.',`<button class="primary-btn" data-quest-sync>Atualizar agora</button>`))}</div>`}

function sessionPage(){const done=state.tasks.filter(task=>task.done).length;return `${sectionHead('PLANEJAMENTO LEVE','Sua sessão de hoje',`<span class="pill">${done}/${state.tasks.length} concluídas</span>`)}<div class="session-grid"><section class="card"><h2>Ações escolhidas</h2><p class="muted">Poucas ações, sem pressão. Marcar uma já faz a sessão valer.</p><div class="task-list">${state.tasks.map(task=>`<div class="task-row ${task.done?'done':''}"><label><input type="checkbox" data-task-check="${task.id}" ${task.done?'checked':''}><span>${esc(task.text)}</span></label><div><button data-task-edit="${task.id}">Editar</button><button class="danger" data-task-delete="${task.id}">Excluir</button></div></div>`).join('')||emptyState('◷','Sessão vazia','Adicione uma ação pequena para começar.')}</div><form class="inline-form" data-task-form><input name="text" maxlength="100" required placeholder="Adicionar uma ação pequena..."><select name="goalId"><option value="">Sem meta vinculada</option>${state.goals.filter(g=>g.status!=='archived').map(g=>`<option value="${g.id}">${esc(g.title)}</option>`).join('')}</select><button class="primary-btn">Adicionar</button></form></section><section class="card"><h2>Registrar resultado</h2><p class="muted">Isso alimenta automaticamente o seu Histórico.</p><form class="form" data-session-log><label>Atividade<input name="title" required placeholder="Ex: Vorkath, quest, GOTR..."></label><label>Categoria<select name="type"><option value="progress">Progresso</option><option value="pvm">PvM</option><option value="relax">Relaxar</option><option value="money">Dinheiro</option></select></label><label>Resultado<select name="result"><option>Concluído</option><option>Progresso parcial</option><option>Troquei de atividade</option><option>Parei por hoje</option></select></label><label>Observação<textarea name="detail" placeholder="Como foi? O que ficou para depois?"></textarea></label><button class="primary-btn">Registrar sessão</button></form></section></div>`}

function characterPage(){const closest=state.skills.filter(item=>item.target>item.current).sort((a,b)=>(a.target-a.current)-(b.target-b.current)).slice(0,3);const base=Math.min(...state.skills.map(item=>item.current));return `${sectionHead('WISE OLD MAN + METAS','Ficha do personagem',`<button class="primary-btn" data-sync>↻ Atualizar conta</button>`)}<div class="character-summary"><div><span>Total level</span><strong>${state.total}</strong><small>meta ${state.totalGoal}</small></div><div><span>Base atual</span><strong>${base}</strong><small>menor skill</small></div><div><span>Mais próxima</span><strong>${closest[0]?.name||'—'}</strong><small>${closest[0]?`${closest[0].target-closest[0].current} níveis`:'metas atingidas'}</small></div><div><span>Último sync</span><strong>${state.lastSync?formatDate(state.lastSync):'—'}</strong><small>Wise Old Man</small></div></div><div class="character-layout"><section class="card skill-panel">${sectionHead('24 SKILLS','Níveis e metas')}<div class="skill-list">${state.skills.map(item=>{const achieved=item.current>=item.target;return `<div class="skill-row ${achieved?'achieved':''}"><img src="assets/${item.name.toLowerCase()}-icon.png" alt=""><div><strong>${item.name}</strong>${progressBar(item.current/item.target*100)}</div><span>${item.current}</span><label>/ <input type="number" min="1" max="99" value="${item.target}" data-skill-target="${item.name}" aria-label="Meta de ${item.name}"></label><button data-skill-goal="${item.name}" title="Criar meta">＋</button></div>`}).join('')}</div><button class="primary-btn" data-save-skills>Salvar metas de nível</button></section><aside class="card checkpoint-panel">${sectionHead('CHECKPOINTS','Onde você está')}<div class="checkpoint"><span>Base 70</span><strong>${base>=70?'Concluído':`${base}/70`}</strong></div><div class="checkpoint"><span>Prayer 77</span><strong>${skill('Prayer')?.current}/77</strong></div><div class="checkpoint"><span>2000 Total</span><strong>${state.total}/${state.totalGoal}</strong></div><h3>Próximas metas</h3>${closest.map(item=>`<button data-skill-goal="${item.name}"><img src="assets/${item.name.toLowerCase()}-icon.png" alt=""><span>${item.name}</span><small>${item.current} → ${item.target}</small></button>`).join('')}</aside></div>`}

function bossProgress(bossId){if(!state.bosses.progress[bossId])state.bosses.progress[bossId]={kc:0,target:25,status:'Nunca tentei',best:'',gear:'',notes:'',liked:false,project:false,image:''};return state.bosses.progress[bossId]}
function bossImage(item,progress){return progress.image||item.image||`https://oldschool.runescape.wiki/w/Special:FilePath/${encodeURIComponent(item.name.replace(/’/g,"'"))}.png`}
function bossCard(item){const data=bossProgress(item.id),value=clamp(data.kc/Math.max(1,data.target)*100);return `<article class="boss-card card ${data.project?'project':''}"><button class="boss-main" data-boss-edit="${item.id}"><span class="boss-art"><img src="${bossImage(item,data)}" alt="${esc(item.name)}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><b hidden>${esc(item.name.slice(0,2).toUpperCase())}</b></span><span class="boss-copy"><small>${esc(item.category)} · ${esc(data.status)}</small><strong>${esc(item.name)}</strong><em>${data.kc} KC · meta ${data.target}</em>${progressBar(value)}</span><span class="pill">${Math.round(value)}%</span></button><div class="boss-actions"><button data-boss-kc="${item.id}">+ KC</button><button data-boss-edit="${item.id}">Detalhes</button></div></article>`}
function raidCard(item){const value=clamp(item.current/Math.max(1,item.target)*100);return `<article class="raid-card card ${statusClass(item.status)}"><button data-raid-edit="${item.id}"><span class="raid-mark">${item.id==='toa'?'𓂀':item.id==='cox'?'✦':'☠'}</span><span><small>${esc(item.mode)} · ${statusLabel(item.status)}</small><strong>${esc(item.name)}</strong><em>${item.current} / ${item.target}</em>${progressBar(value)}</span><b>${Math.round(value)}%</b></button><div><button data-raid-step="${item.id}">+ ${item.id==='toa'?'10 Invocation':'progresso'}</button><button data-raid-edit="${item.id}">Editar</button></div></article>`}
function pvmPage(){const selected=state.bosses.selected.map(bossId=>state.bosses.catalog.find(item=>item.id===bossId)).filter(Boolean);const raids=state.raids.selected.map(raidId=>state.raids.items[raidId]).filter(Boolean);return `${sectionHead('CENTRAL PVM','Bosses e raids',`<div class="seg-actions"><button class="ghost-btn" data-boss-manager>⚙ Bosses</button><button class="ghost-btn" data-raid-manager>⚙ Raids</button></div>`)}${ui.bossManager?bossManager():''}${ui.raidManager?raidManager():''}<section class="pvm-section">${sectionHead('PASSAPORTE','Bosses selecionados',`<span class="pill">${selected.filter(item=>bossProgress(item.id).kc>0).length}/${selected.length} experimentados</span>`)}<div class="boss-grid">${selected.map(bossCard).join('')||emptyState('⚔','Nenhum boss selecionado','Abra o catálogo e escolha o que acompanhar.',`<button class="primary-btn" data-boss-manager>Escolher bosses</button>`)}</div></section><section class="pvm-section raids">${sectionHead('RAIDS E INVOCATIONS','Campanha de domínio')}<div class="raid-grid">${raids.map(raidCard).join('')||emptyState('𓂀','Nenhuma raid selecionada','Escolha as raids que quer acompanhar.')}</div></section>`}
function bossManager(){const categories=['all',...new Set(state.bosses.catalog.map(item=>item.category))];const visible=state.bosses.catalog.filter(item=>ui.bossCategory==='all'||item.category===ui.bossCategory).filter(item=>item.name.toLowerCase().includes(ui.bossSearch.toLowerCase()));return `<section class="manager card">${sectionHead('CONFIGURAR PASSAPORTE','Escolha seus bosses',`<button class="icon-btn" data-boss-manager>×</button>`)}<div class="filterbar"><label class="search"><span>⌕</span><input data-boss-search value="${esc(ui.bossSearch)}" placeholder="Pesquisar boss..."></label><select data-boss-category>${categories.map(category=>`<option value="${esc(category)}" ${ui.bossCategory===category?'selected':''}>${category==='all'?'Todas as categorias':esc(category)}</option>`).join('')}</select><button class="ghost-btn" data-boss-select-all>Selecionar visíveis</button></div><div class="catalog-grid">${visible.map(item=>{const checked=state.bosses.selected.includes(item.id);return `<label class="catalog-item ${checked?'selected':''}"><input type="checkbox" data-boss-select="${item.id}" ${checked?'checked':''}><span class="catalog-thumb"><img src="${bossImage(item,bossProgress(item.id))}" alt="" onerror="this.hidden=true"></span><span><strong>${esc(item.name)}</strong><small>${esc(item.category)}</small></span></label>`}).join('')}</div><form class="inline-form" data-custom-boss><input name="name" required placeholder="Adicionar conteúdo personalizado..."><input name="category" value="Personalizado" placeholder="Categoria"><button class="primary-btn">Adicionar</button></form></section>`}
function raidManager(){return `<section class="manager card">${sectionHead('CONFIGURAR RAIDS','Escolha suas campanhas',`<button class="icon-btn" data-raid-manager>×</button>`)}<div class="raid-select">${Object.values(state.raids.items).map(item=>`<label><input type="checkbox" data-raid-select="${item.id}" ${state.raids.selected.includes(item.id)?'checked':''}><span><strong>${esc(item.name)}</strong><small>${esc(item.mode)}</small></span></label>`).join('')}</div></section>`}

function historyPage(){const visible=state.history.filter(event=>ui.historyFilter==='all'||event.type===ui.historyFilter);return `${sectionHead('DIÁRIO AUTOMÁTICO','O que já aconteceu',`<button class="ghost-btn" data-export-history>Exportar histórico</button>`)}<div class="filterbar"><select data-history-filter><option value="all">Todos os registros</option>${[['goal','Metas'],['sync','Sincronizações'],['session','Sessões'],['pvm','PvM'],['milestone','Marcos']].map(([value,label])=>`<option value="${value}" ${ui.historyFilter===value?'selected':''}>${label}</option>`).join('')}</select><span>${visible.length} acontecimentos</span></div><div class="timeline">${visible.map(event=>`<article><span class="timeline-dot">${event.type==='goal'?'✓':event.type==='sync'?'↻':event.type==='pvm'?'⚔':'✦'}</span><div><small>${formatDate(event.date)}</small><strong>${esc(event.title)}</strong><p>${esc(event.detail)}</p></div><button data-history-delete="${event.id}" aria-label="Excluir registro">×</button></article>`).join('')||emptyState('▤','Histórico vazio','Suas sessões e conquistas aparecerão aqui.')}</div>`}

function customizePage(){const widgetNames={today:'Sessão de hoje',journey:'Era atual',focus:'Foco atual',upcoming:'Próximos desbloqueios',character:'Meu personagem',recent:'Últimas conquistas'};return `${sectionHead('PERSONALIZAÇÃO','Monte o painel do seu jeito')}<div class="customize-grid"><section class="card"><h2>Aparência</h2><div class="theme-presets"><button data-theme="wallpaper" class="${state.preferences.background==='wallpaper'?'selected':''}">Mar de Gielinor</button><button data-theme="map" class="${state.preferences.background==='map'?'selected':''}">Mapa clássico</button><button data-theme="plain" class="${state.preferences.background==='plain'?'selected':''}">Escuro limpo</button></div><form class="form" data-preferences><label>Cor de destaque<input name="accent" type="color" value="${state.preferences.accent}"></label><label>Opacidade dos cards <output>${state.preferences.cardOpacity}%</output><input name="cardOpacity" type="range" min="72" max="100" value="${state.preferences.cardOpacity}"></label><label>Densidade<select name="density"><option value="comfortable" ${state.preferences.density==='comfortable'?'selected':''}>Confortável</option><option value="compact" ${state.preferences.density==='compact'?'selected':''}>Compacta</option></select></label><label class="switch"><input name="motion" type="checkbox" ${state.preferences.motion?'checked':''}><span>Animações e efeitos</span></label><label>Página inicial<select name="startPage">${navItems.filter(item=>!['customize','settings'].includes(item[0])).map(item=>`<option value="${item[0]}" ${state.preferences.startPage===item[0]?'selected':''}>${item[2]}</option>`).join('')}</select></label><button class="primary-btn">Aplicar aparência</button></form></section><section class="card"><h2>Trilha sonora</h2><p class="muted">${osrsTracks.length} clássicos de Gielinor. Ao terminar uma faixa, a próxima começa automaticamente.</p><div class="music-roster">${osrsTracks.map((track,index)=>`<button data-music-pick="${index}" class="${ui.musicIndex===index?'active':''}"><i>${ui.musicIndex===index&&ui.musicPlaying?'♫':index+1}</i><span><strong>${esc(track.name)}</strong><small>${esc(track.area)}</small></span><b>${ui.musicIndex===index?'Selecionada':'Tocar'}</b></button>`).join('')}</div><label class="music-settings-volume">Volume da música <output>${state.preferences.musicVolume}%</output><input data-music-volume type="range" min="0" max="100" value="${state.preferences.musicVolume}"></label><div class="music-settings-actions"><button class="primary-btn" data-music-toggle>${ui.musicPlaying?'Ⅱ Pausar':'▶ Tocar música'}</button><button class="ghost-btn" data-music-next>Próxima faixa →</button></div></section><section class="card"><h2>Widgets da Home</h2><p class="muted">Escolha o que aparece e a ordem dos painéis.</p><div class="widget-list">${state.dashboard.widgets.map((key,index)=>`<div><label><input type="checkbox" data-widget-visible="${key}" ${!state.dashboard.hidden.includes(key)?'checked':''}><span>${widgetNames[key]}</span></label><aside><button data-widget-up="${key}" ${index===0?'disabled':''}>↑</button><button data-widget-down="${key}" ${index===state.dashboard.widgets.length-1?'disabled':''}>↓</button></aside></div>`).join('')}</div><button class="ghost-btn" data-route="dashboard">Ver minha Home</button></section><section class="card"><h2>Imagem de fundo personalizada</h2><p class="muted">A imagem será redimensionada antes de ser salva para não pesar no navegador.</p>${state.preferences.customBackground?`<div class="background-preview" style="background-image:url('${state.preferences.customBackground}')"></div>`:''}<button class="ghost-btn" data-background-upload>Escolher imagem</button>${state.preferences.customBackground?'<button class="ghost-btn danger" data-background-remove>Remover imagem</button>':''}</section></div>`}

function settingsPage(){return `${sectionHead('CONTA E DADOS','Configurações')}<div class="settings-grid"><section class="card"><h2>Wise Old Man</h2><p class="muted">Atualiza as 24 skills, o total level e os KCs públicos do personagem selecionado.</p><form class="form" data-sync-form><label>Nick da conta<input name="username" value="${esc(state.username)}" required></label><button class="primary-btn">↻ Atualizar agora</button></form><small>${state.lastSync?`Última atualização: ${esc(state.lastSync)}`:'Ainda não sincronizado.'}</small></section><section class="card"><h2>WikiSync de quests</h2><p class="muted">Lê as quests do personagem atual enviadas pelo RuneLite.</p><button class="primary-btn" data-quest-sync>↻ Atualizar quests</button><small>${state.quests.lastSync?`Última atualização: ${formatDate(state.quests.lastSync)}`:'Abra o RuneLite com o WikiSync ativo para enviar seu diário.'}</small></section><section class="card"><h2>Identidade</h2><form class="form" data-account-form><label>Nome do painel<input name="account" value="${esc(state.account)}"></label><label>Próximo marco total<input name="totalGoal" type="number" min="1" value="${state.totalGoal}"></label><button class="primary-btn">Salvar</button></form><button class="ghost-btn" data-route="profiles">Gerenciar personagens</button></section><section class="card"><h2>Backup completo</h2><p class="muted">Inclui todos os personagens com metas, quests, histórico, PvM e personalização.</p><div class="stack-actions"><button class="primary-btn" data-export>Exportar todos os personagens</button><button class="ghost-btn" data-import>Importar backup</button><button class="ghost-btn danger" data-reset>Reiniciar personagem atual</button></div></section></div>`}

function drawer(){let body='';const data=ui.drawer;if(data.type==='profile')body=profileDrawer(data.id);if(data.type==='goal')body=goalDrawer(data.id,data.eraId,data.questName);if(data.type==='goalMenu')body=goalMenuDrawer(data.id);if(data.type==='era')body=eraDrawer(data.id);if(data.type==='task')body=taskDrawer(data.id);if(data.type==='focus')body=focusDrawer();if(data.type==='boss')body=bossDrawer(data.id);if(data.type==='raid')body=raidDrawer(data.id);return `<div class="drawer-backdrop" data-drawer-backdrop></div><aside class="drawer" role="dialog" aria-modal="true">${body}</aside>`}
function drawerHead(kicker,title){return `<div class="drawer-head"><div><span class="eyebrow">${kicker}</span><h2>${esc(title)}</h2></div><button class="icon-btn" data-close-drawer aria-label="Fechar">×</button></div>`}
function profileDrawer(profileId){const profile=profileHub.profiles.find(item=>item.id===profileId);return `${drawerHead(profile?'EDITAR PERSONAGEM':'NOVO PERSONAGEM',profile?.name||'Criar aventura')}<form class="form drawer-form" data-profile-form><input type="hidden" name="id" value="${profile?.id||''}"><label>Nome no painel<input name="name" required value="${esc(profile?.name||'')}" placeholder="Ex: Minha Iron"></label><label>Nick no RuneScape<input name="username" required value="${esc(profile?.username||'')}" placeholder="Ex: Iron Samuka"><small>Esse nick será usado no Wise Old Man e no WikiSync.</small></label><label>Tipo da conta<select name="accountType">${[['main','Main'],['ironman','Ironman'],['hardcore','Hardcore Ironman'],['ultimate','Ultimate Ironman'],['group','Group Ironman'],['skiller','Skiller']].map(([value,label])=>`<option value="${value}" ${profile?.accountType===value?'selected':''}>${label}</option>`).join('')}</select></label>${profile?'':`<label>Preset inicial<select name="preset"><option value="iron">Ironman · recomendado para autossuficiência</option><option value="main">Main · jornada geral</option><option value="pvm">PvM · bosses e raids</option><option value="blank">Personalizado · começar vazio</option></select><small>Você poderá editar absolutamente tudo depois.</small></label>`}<button class="primary-btn">${profile?'Salvar personagem':'Criar e entrar'}</button></form>`}
function goalDrawer(goalId,eraId='',questName=''){
  const goal=goalId?goalById(goalId):null,linkedQuest=goal?.questName||questName,quest=questByName(linkedQuest),isQuest=!!linkedQuest,selectedType=goal?.type||(isQuest?'quest':'manual'),selectedMode=goal?.mode||(isQuest?'quest':'manual'),selectedStatus=goal?.status||(Number(quest?.state)===2?'done':Number(quest?.state)===1?'active':'planned'),title=goal?.title||linkedQuest||'',description=goal?.description||(isQuest?`Concluir ${linkedQuest} e avançar na jornada.`:'');
  const availableQuests=[...state.quests.items].filter(item=>Number(item.state)!==2||item.name===linkedQuest).sort((a,b)=>Number(b.state)-Number(a.state)||a.name.localeCompare(b.name));
  return `${drawerHead(goal?'EDITAR META':isQuest?'QUEST NO ROADMAP':'NOVA META',goal?.title||linkedQuest||'Criar objetivo')}<form class="form drawer-form" data-goal-form><input type="hidden" name="id" value="${goal?.id||''}"><label>Nome<input name="title" required value="${esc(title)}" placeholder="Ex: Slayer 85"></label><label>Descrição<textarea name="description" placeholder="Por que essa meta importa?">${esc(description)}</textarea></label><div class="form-two"><label>Tipo<select name="type">${[['manual','Meta livre'],['quest','Quest'],['skill','Skill'],['boss','Boss'],['raid','Raid'],['unlock','Desbloqueio']].map(([value,label])=>`<option value="${value}" ${selectedType===value?'selected':''}>${label}</option>`).join('')}</select></label><label>Status<select name="status">${['planned','active','paused','done'].map(value=>`<option value="${value}" ${selectedStatus===value?'selected':''}>${statusLabel(value)}</option>`).join('')}</select></label></div><label>Capítulo do Roadmap<select name="eraId"><option value="">Sem capítulo</option>${[...state.eras].sort((a,b)=>a.order-b.order).map(era=>`<option value="${era.id}" ${(goal?.eraId||eraId)===era.id?'selected':''}>${esc(era.title)}</option>`).join('')}</select><small>Esta escolha define onde a meta aparecerá no Roadmap.</small></label><label>Como calcular<select name="mode"><option value="manual" ${selectedMode==='manual'?'selected':''}>Porcentagem manual</option><option value="quest" ${selectedMode==='quest'?'selected':''}>Estado da quest no WikiSync</option><option value="skill" ${selectedMode==='skill'?'selected':''}>Nível de skill</option><option value="boss" ${selectedMode==='boss'?'selected':''}>KC de boss</option><option value="raid" ${selectedMode==='raid'?'selected':''}>Progresso de raid</option></select></label><label>Quest vinculada<select name="questName"><option value="">Selecione entre ${availableQuests.length} quests pendentes</option>${availableQuests.map(item=>`<option value="${esc(item.name)}" ${linkedQuest===item.name?'selected':''}>${esc(item.name)} · ${questStateLabel(item.state)}</option>`).join('')}</select><small>São exibidas somente quests não concluídas deste personagem.</small>${linkedQuest?`<small>Progresso atual: ${questProgress(linkedQuest)}% pelo WikiSync.</small>`:''}</label><div class="form-two"><label>Skill<select name="skill"><option value="">Selecione</option>${state.skills.map(item=>`<option ${goal?.skill===item.name?'selected':''}>${item.name}</option>`).join('')}</select></label><label>Boss<select name="bossId"><option value="">Selecione</option>${state.bosses.catalog.map(item=>`<option value="${item.id}" ${goal?.bossId===item.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label></div><div class="form-two"><label>Raid<select name="raidId"><option value="">Selecione</option>${Object.values(state.raids.items).map(item=>`<option value="${item.id}" ${goal?.raidId===item.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label><label>Meta numérica<input name="target" type="number" min="1" value="${goal?.target||100}"></label></div><label>Progresso manual (%)<input name="progress" type="range" min="0" max="100" value="${goal?.progress||0}"></label><button class="primary-btn">${goal?'Salvar alterações':isQuest?'Adicionar ao Roadmap':'Criar meta'}</button></form>`
}
function goalMenuDrawer(goalId){const goal=goalById(goalId);return `${drawerHead('AÇÕES DA META',goal.title)}<div class="drawer-summary">${goalCard(goal,true)}</div><div class="action-list"><button data-goal-edit="${goal.id}">✎ Editar meta</button><button data-goal-up="${goal.id}">↑ Subir na ordem</button><button data-goal-down="${goal.id}">↓ Descer na ordem</button><button data-goal-focus="${goal.id}">✦ Adicionar ao foco</button><button data-goal-today="${goal.id}">◷ Criar ação para hoje</button><button data-goal-archive="${goal.id}">▤ ${goal.status==='archived'?'Restaurar meta':'Arquivar meta'}</button><button class="danger" data-goal-delete="${goal.id}">× Excluir meta</button></div>`}
function eraDrawer(eraId){const era=state.eras.find(item=>item.id===eraId);return `${drawerHead(era?'EDITAR CAPÍTULO':'NOVO CAPÍTULO',era?.title||'Construir etapa')}<form class="form drawer-form" data-era-form><input type="hidden" name="id" value="${era?.id||''}"><label>Nome<input name="title" required value="${esc(era?.title||'')}"></label><label>Descrição<textarea name="description">${esc(era?.description||'')}</textarea></label><button class="primary-btn">Salvar capítulo</button>${era?`<button type="button" class="ghost-btn danger" data-era-delete="${era.id}">Excluir capítulo</button>`:''}</form>`}
function taskDrawer(taskId){const task=state.tasks.find(item=>item.id===taskId);return `${drawerHead('EDITAR AÇÃO','Sessão de hoje')}<form class="form drawer-form" data-task-edit-form><input type="hidden" name="id" value="${task.id}"><label>Ação<input name="text" required maxlength="100" value="${esc(task.text)}"></label><label>Meta vinculada<select name="goalId"><option value="">Sem meta</option>${state.goals.filter(g=>g.status!=='archived').map(g=>`<option value="${g.id}" ${task.goalId===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label><button class="primary-btn">Salvar ação</button></form>`}
function focusDrawer(){return `${drawerHead('ORGANIZAR HOME','Foco e desbloqueios')}<form class="form drawer-form" data-focus-form><p class="muted">Escolha até três metas para o foco atual.</p>${[0,1,2].map(index=>`<label>Foco ${index+1}<select name="focus"><option value="">Nenhuma</option>${state.goals.filter(g=>g.status!=='archived').map(g=>`<option value="${g.id}" ${state.dashboard.focus[index]===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label>`).join('')}<h3>Próximos desbloqueios</h3><div class="upcoming-config">${state.dashboard.upcoming.map((goalId,index)=>{const goal=goalById(goalId);return goal?`<div><span>${index+1}. ${esc(goal.title)}</span><aside><button type="button" data-upcoming-up="${goalId}" ${index===0?'disabled':''}>↑</button><button type="button" data-upcoming-down="${goalId}" ${index===state.dashboard.upcoming.length-1?'disabled':''}>↓</button><button type="button" data-upcoming-remove="${goalId}">×</button></aside></div>`:''}).join('')}</div><div class="inline-form"><select id="upcomingAdd"><option value="">Adicionar desbloqueio...</option>${state.goals.filter(g=>g.status!=='archived'&&!state.dashboard.upcoming.includes(g.id)).map(g=>`<option value="${g.id}">${esc(g.title)}</option>`).join('')}</select><button type="button" class="ghost-btn" data-upcoming-add>Adicionar</button></div><button class="primary-btn">Salvar painel</button></form>`}
function bossDrawer(bossId){const item=state.bosses.catalog.find(b=>b.id===bossId),data=bossProgress(bossId);return `${drawerHead('EDITAR PASSAPORTE',item.name)}<div class="boss-editor-preview"><img src="${bossImage(item,data)}" alt=""></div><form class="form drawer-form" data-boss-form><input type="hidden" name="id" value="${item.id}"><label>Imagem manual<input name="image" type="file" accept="image/png,image/jpeg,image/webp"><small>Será redimensionada antes de salvar.</small></label>${data.image?'<button type="button" class="ghost-btn" data-boss-image-remove>Usar imagem da Wiki</button>':''}<div class="form-two"><label>KC atual<input name="kc" type="number" min="0" value="${data.kc}"></label><label>Meta de KC<input name="target" type="number" min="1" value="${data.target}"></label></div><label>Estado<input name="status" value="${esc(data.status)}" placeholder="Aprendendo, consistente..."></label><label>Melhor marca<input name="best" value="${esc(data.best)}"></label><label>Gear<textarea name="gear">${esc(data.gear)}</textarea></label><label>Observações<textarea name="notes">${esc(data.notes)}</textarea></label><label class="switch"><input name="project" type="checkbox" ${data.project?'checked':''}><span>Projeto atual</span></label><button class="primary-btn">Salvar boss</button><button type="button" class="ghost-btn" data-boss-hide="${item.id}">Ocultar do painel</button></form>`}
function raidDrawer(raidId){const item=state.raids.items[raidId];return `${drawerHead('EDITAR CAMPANHA',item.name)}<form class="form drawer-form" data-raid-form><input type="hidden" name="id" value="${item.id}"><label>Modo de progresso<input name="mode" value="${esc(item.mode)}"></label><div class="form-two"><label>Atual<input name="current" type="number" min="0" value="${item.current}"></label><label>Meta<input name="target" type="number" min="1" value="${item.target}"></label></div><label>Status<select name="status">${['new','active','paused','done'].map(value=>`<option value="${value}" ${item.status===value?'selected':''}>${value==='new'?'Nunca tentei':statusLabel(value)}</option>`).join('')}</select></label><label>Melhor marca<input name="best" value="${esc(item.best)}"></label><label>Observações<textarea name="notes">${esc(item.notes)}</textarea></label><button class="primary-btn">Salvar raid</button></form>`}

function pageContent(){return ({dashboard:dashboardPage,profiles:profilesPage,roadmap:roadmapPage,goals:goalsPage,quests:questsPage,session:sessionPage,character:characterPage,pvm:pvmPage,history:historyPage,customize:customizePage,settings:settingsPage}[route]||dashboardPage)()}
function drawerKey(data=ui.drawer){return data?`${data.type}:${data.id||data.questName||data.eraId||'new'}`:''}
function captureDrawerDraft(){const drawer=$('.drawer'),form=drawer?.querySelector('form');if(!drawer||!form)return null;const elements=[...form.elements];return {scrollTop:drawer.scrollTop,activeIndex:elements.indexOf(document.activeElement),fields:elements.map(element=>({name:element.name,type:element.type,value:element.type==='file'?'':element.value,checked:element.checked}))}}
function restoreDrawerDraft(draft){const drawer=$('.drawer'),form=drawer?.querySelector('form');if(!draft||!drawer||!form)return;const elements=[...form.elements];draft.fields.forEach((field,index)=>{const element=elements[index];if(!element||element.name!==field.name||element.type==='file')return;if(['checkbox','radio'].includes(element.type))element.checked=field.checked;else element.value=field.value});drawer.scrollTop=draft.scrollTop;const active=elements[draft.activeIndex];if(active&&typeof active.focus==='function'){active.focus({preventScroll:true});drawer.scrollTop=draft.scrollTop}}
function capturePageFocus(){const active=document.activeElement;if(!active||active.closest('.drawer'))return null;const selector=active.matches('[data-goal-search]')?'[data-goal-search]':active.matches('[data-quest-search]')?'[data-quest-search]':active.matches('[data-boss-search]')?'[data-boss-search]':null;if(!selector)return null;return {selector,start:active.selectionStart,end:active.selectionEnd}}
function restorePageFocus(focus){if(!focus)return;const active=$(focus.selector);if(!active)return;active.focus({preventScroll:true});if(typeof active.setSelectionRange==='function')active.setSelectionRange(focus.start,focus.end)}
function normalizeButtonTypes(){$$('button:not([type])').forEach(button=>{const form=button.closest('form'),isPlainSubmit=form&&!Object.keys(button.dataset).length;button.type=isPlainSubmit?'submit':'button';if(isPlainSubmit&&form.closest('.drawer'))button.dataset.drawerSave=''})}
function render(){const nextDrawerKey=drawerKey(),pageFocus=capturePageFocus(),captured=!ui.skipDrawerDraft&&ui.renderedDrawerKey?captureDrawerDraft():null;if(captured)ui.drawerDrafts[ui.renderedDrawerKey]=captured;document.body.classList.toggle('reduce-motion',!state.preferences.motion);document.body.classList.toggle('compact-density',state.preferences.density==='compact');document.body.dataset.route=route;$('#app').innerHTML=appShell(pageContent());normalizeButtonTypes();ui.renderedDrawerKey=nextDrawerKey;restoreDrawerDraft(ui.drawerDrafts[nextDrawerKey]);restorePageFocus(pageFocus);ui.skipDrawerDraft=false;ui.routeEntering=false;applyPreferences();}
function applyPreferences(){document.documentElement.style.setProperty('--accent',state.preferences.accent);document.documentElement.style.setProperty('--card-alpha',String(state.preferences.cardOpacity/100));document.body.dataset.background=state.preferences.background;if(state.preferences.customBackground)document.documentElement.style.setProperty('--custom-bg',`url("${state.preferences.customBackground}")`);else document.documentElement.style.removeProperty('--custom-bg');syncMusicPlayer()}
function musicAudio(){return $('#osrsPlayer')}
function updateMusicUI(){const track=osrsTracks[ui.musicIndex];$$('[data-music-label]').forEach(element=>element.textContent=track.name);$$('[data-music-area]').forEach(element=>element.textContent=track.area);$$('[data-music-toggle]').forEach(button=>{button.innerHTML=button.closest('.music-settings-actions')?(ui.musicPlaying?'Ⅱ Pausar':'▶ Tocar música'):(ui.musicPlaying?'Ⅱ':'▶');button.setAttribute('aria-label',ui.musicPlaying?'Pausar música':'Tocar música')});$$('.music-player').forEach(player=>player.classList.toggle('playing',ui.musicPlaying));$$('[data-music-pick]').forEach(button=>{const active=Number(button.dataset.musicPick)===ui.musicIndex;button.classList.toggle('active',active);const icon=button.querySelector('i'),label=button.querySelector('b');if(icon)icon.textContent=active&&ui.musicPlaying?'♫':Number(button.dataset.musicPick)+1;if(label)label.textContent=active?'Selecionada':'Tocar'});$$('[data-music-volume]').forEach(input=>input.value=state.preferences.musicVolume);$$('.music-settings-volume output').forEach(output=>output.textContent=`${state.preferences.musicVolume}%`)}
function syncMusicPlayer(){const audio=musicAudio();if(!audio)return;const desired=Number(state.preferences.musicTrack);if(Number.isInteger(desired)&&desired>=0&&desired<osrsTracks.length)ui.musicIndex=desired;const track=osrsTracks[ui.musicIndex];if(audio.dataset.track!==String(ui.musicIndex)){audio.src=track.url;audio.dataset.track=String(ui.musicIndex);audio.load()}audio.volume=Math.max(0,Math.min(1,(Number(state.preferences.musicVolume)||0)/100));updateMusicUI()}
async function selectMusic(index,autoplay=ui.musicPlaying,message='Faixa alterada'){const total=osrsTracks.length;ui.musicIndex=(Number(index)+total)%total;state.preferences.musicTrack=ui.musicIndex;syncMusicPlayer();save(message,true);if(autoplay){try{await musicAudio().play()}catch{ui.musicPlaying=false;updateMusicUI();toast('Clique em tocar para iniciar a trilha sonora.')}}}
async function toggleMusic(){const audio=musicAudio();if(!audio)return;if(audio.paused){try{await audio.play()}catch{toast('Não foi possível tocar esta faixa agora.')}}else audio.pause()}
function formatDate(value){const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value||'');return date.toLocaleString('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}
function moveInArray(array,value,direction){const index=array.indexOf(value),target=index+direction;if(index<0||target<0||target>=array.length)return;[array[index],array[target]]=[array[target],array[index]]}

document.addEventListener('click',async event=>{
  if(event.target.matches('[data-drawer-backdrop]')){ui.drawer=null;render();return}
  const button=event.target.closest('button,[data-close-menu]');if(!button)return;
  if(button.dataset.route){navigate(button.dataset.route);return}
  if(button.matches('[data-menu]')){ui.menu=!ui.menu;render();return}
  if(button.matches('[data-close-menu]')){ui.menu=false;render();return}
  if(button.matches('[data-close-drawer]')){ui.drawer=null;render();return}
  if(button.matches('[data-focus]')){document.body.classList.toggle('focus-mode');return}
  if(button.matches('[data-toggle-dashboard-edit]')){ui.customize=!ui.customize;render();return}
  if(button.dataset.profileNew!==undefined){ui.drawer={type:'profile'};render();return}
  if(button.dataset.profileEdit){ui.drawer={type:'profile',id:button.dataset.profileEdit};render();return}
  if(button.dataset.profileSwitch){await activateProfile(button.dataset.profileSwitch);return}
  if(button.dataset.profileDelete){if(!confirm('Excluir este personagem e todos os dados locais dele?'))return;const deletingId=button.dataset.profileDelete,wasActive=deletingId===profileHub.activeId;activeProfile().state=state;profileHub.profiles=profileHub.profiles.filter(profile=>profile.id!==deletingId);if(wasActive){profileHub.activeId=profileHub.profiles[0].id;state=mergeDefaults(activeProfile().state)}persistProfiles();ui.drawer=null;navigate('profiles');toast('Personagem excluído');return}
  if(button.dataset.widgetUp){moveInArray(state.dashboard.widgets,button.dataset.widgetUp,-1);save('Painel reorganizado');render();return}
  if(button.dataset.widgetDown){moveInArray(state.dashboard.widgets,button.dataset.widgetDown,1);save('Painel reorganizado');render();return}
  if(button.dataset.widgetHide){state.dashboard.hidden.push(button.dataset.widgetHide);save('Painel ocultado');render();return}
  if(button.dataset.dashboardFocus!==undefined){ui.drawer={type:'focus'};render();return}
  if(button.dataset.upcomingUp){moveInArray(state.dashboard.upcoming,button.dataset.upcomingUp,-1);save('Ordem atualizada',true);render();return}
  if(button.dataset.upcomingDown){moveInArray(state.dashboard.upcoming,button.dataset.upcomingDown,1);save('Ordem atualizada',true);render();return}
  if(button.dataset.upcomingRemove){state.dashboard.upcoming=state.dashboard.upcoming.filter(item=>item!==button.dataset.upcomingRemove);save('Desbloqueio removido',true);render();return}
  if(button.dataset.upcomingAdd!==undefined){const value=$('#upcomingAdd')?.value;if(value&&!state.dashboard.upcoming.includes(value)){state.dashboard.upcoming.push(value);save('Desbloqueio adicionado',true);render()}return}
  if(button.dataset.goalNew!==undefined){ui.drawer={type:'goal'};render();return}
  if(button.dataset.goalNewEra){ui.drawer={type:'goal',eraId:button.dataset.goalNewEra};render();return}
  if(button.dataset.questGoal){const questName=button.dataset.questGoal,goal=state.goals.find(item=>item.mode==='quest'&&item.questName===questName&&item.status!=='archived');const currentEra=state.eras.find(era=>state.goals.some(item=>item.eraId===era.id&&item.status==='active'))||[...state.eras].sort((a,b)=>a.order-b.order)[0];ui.drawer=goal?{type:'goal',id:goal.id}:{type:'goal',questName,eraId:currentEra?.id||''};render();return}
  if(button.dataset.questSync!==undefined){await syncQuests();return}
  if(button.dataset.goalOpen){ui.drawer={type:'goalMenu',id:button.dataset.goalOpen};render();return}
  if(button.dataset.goalMenu){ui.drawer={type:'goalMenu',id:button.dataset.goalMenu};render();return}
  if(button.dataset.goalEdit){ui.drawer={type:'goal',id:button.dataset.goalEdit};render();return}
  if(button.dataset.goalUp){const ordered=[...state.goals].sort((a,b)=>a.priority-b.priority),goal=goalById(button.dataset.goalUp);moveInArray(ordered,goal,-1);ordered.forEach((item,index)=>item.priority=index+1);save('Meta reordenada');render();return}
  if(button.dataset.goalDown){const ordered=[...state.goals].sort((a,b)=>a.priority-b.priority),goal=goalById(button.dataset.goalDown);moveInArray(ordered,goal,1);ordered.forEach((item,index)=>item.priority=index+1);save('Meta reordenada');render();return}
  if(button.dataset.goalProgress){const [goalId,value]=button.dataset.goalProgress.split(':');const goal=goalById(goalId);if(!goal||goal.mode!=='manual')return;const before=goal.status;goal.progress=Number(value);goal.status=Number(value)===100?'done':'active';if(goal.status==='done'&&before!=='done')addHistory('goal',`${goal.title} concluída`,'Meta marcada como concluída.');save('Progresso atualizado');render();return}
  if(button.dataset.goalFocus){if(!state.dashboard.focus.includes(button.dataset.goalFocus)){state.dashboard.focus=[button.dataset.goalFocus,...state.dashboard.focus].slice(0,3)}save('Meta adicionada ao foco');ui.drawer=null;render();return}
  if(button.dataset.goalToday){const goal=goalById(button.dataset.goalToday);state.tasks.push({id:id('task'),text:`Avançar: ${goal.title}`,done:false,goalId:goal.id});save('Ação adicionada à sessão');ui.drawer=null;render();return}
  if(button.dataset.goalArchive){const goal=goalById(button.dataset.goalArchive);goal.status=goal.status==='archived'?'planned':'archived';save(goal.status==='archived'?'Meta arquivada':'Meta restaurada');ui.drawer=null;render();return}
  if(button.dataset.goalDelete){if(confirm('Excluir esta meta?')){snapshotForUndo();const goalId=button.dataset.goalDelete;state.goals=state.goals.filter(goal=>goal.id!==goalId);state.dashboard.focus=state.dashboard.focus.filter(item=>item!==goalId);state.dashboard.upcoming=state.dashboard.upcoming.filter(item=>item!==goalId);state.tasks.forEach(task=>{if(task.goalId===goalId)task.goalId=null});save('Meta excluída','Desfazer');ui.drawer=null;render()}return}
  if(button.dataset.eraNew!==undefined){ui.drawer={type:'era'};render();return}
  if(button.dataset.eraEdit){ui.drawer={type:'era',id:button.dataset.eraEdit};render();return}
  if(button.dataset.eraUp){const ordered=[...state.eras].sort((a,b)=>a.order-b.order);const item=ordered.find(e=>e.id===button.dataset.eraUp);moveInArray(ordered,item,-1);ordered.forEach((era,index)=>era.order=index);save('Roadmap reorganizado');render();return}
  if(button.dataset.eraDown){const ordered=[...state.eras].sort((a,b)=>a.order-b.order);const item=ordered.find(e=>e.id===button.dataset.eraDown);moveInArray(ordered,item,1);ordered.forEach((era,index)=>era.order=index);save('Roadmap reorganizado');render();return}
  if(button.dataset.eraDelete){if(confirm('Excluir este capítulo? As metas ficarão sem capítulo.')){const eraId=button.dataset.eraDelete;state.eras=state.eras.filter(era=>era.id!==eraId);state.goals.forEach(goal=>{if(goal.eraId===eraId)goal.eraId=null});save('Capítulo excluído');ui.drawer=null;render()}return}
  if(button.dataset.taskEdit){ui.drawer={type:'task',id:button.dataset.taskEdit};render();return}
  if(button.dataset.taskDelete){snapshotForUndo();state.tasks=state.tasks.filter(task=>task.id!==button.dataset.taskDelete);save('Ação excluída','Desfazer');render();return}
  if(button.dataset.skillGoal){const item=skill(button.dataset.skillGoal);let goal=state.goals.find(g=>g.mode==='skill'&&g.skill===item.name&&g.status!=='archived');if(!goal){goal={id:id('goal'),title:`${item.name} ${item.target}`,description:`Evoluir ${item.name} até o nível ${item.target}.`,type:'skill',status:'active',mode:'skill',skill:item.name,target:item.target,eraId:null,priority:state.goals.length+1};state.goals.push(goal);save('Meta de skill criada')}ui.drawer={type:'goal',id:goal.id};render();return}
  if(button.matches('[data-save-skills]')){$$('[data-skill-target]').forEach(input=>skill(input.dataset.skillTarget).target=Number(input.value)||skill(input.dataset.skillTarget).target);save('Metas de nível salvas');render();return}
  if(button.matches('[data-sync]')){await syncAccount();return}
  if(button.matches('[data-boss-manager]')){ui.bossManager=!ui.bossManager;ui.raidManager=false;render();return}
  if(button.matches('[data-raid-manager]')){ui.raidManager=!ui.raidManager;ui.bossManager=false;render();return}
  if(button.dataset.bossEdit){ui.drawer={type:'boss',id:button.dataset.bossEdit};render();return}
  if(button.dataset.bossKc){const data=bossProgress(button.dataset.bossKc);data.kc++;data.status=data.kc===1?'Primeiro KC':data.kc>=50?'Consistente':'Aprendendo';addHistory('pvm',`${state.bosses.catalog.find(b=>b.id===button.dataset.bossKc)?.name}: ${data.kc} KC`,'KC atualizado no Passaporte.');save('+1 KC registrado');render();return}
  if(button.dataset.bossHide){state.bosses.selected=state.bosses.selected.filter(item=>item!==button.dataset.bossHide);save('Boss ocultado; progresso preservado');ui.drawer=null;render();return}
  if(button.matches('[data-boss-image-remove]')){const data=bossProgress(ui.drawer.id);data.image='';save('Imagem manual removida');render();return}
  if(button.matches('[data-boss-select-all]')){$$('[data-boss-select]').forEach(input=>{if(!state.bosses.selected.includes(input.dataset.bossSelect))state.bosses.selected.push(input.dataset.bossSelect);input.checked=true;input.closest('.catalog-item').classList.add('selected')});save('Bosses visíveis selecionados');return}
  if(button.dataset.raidEdit){ui.drawer={type:'raid',id:button.dataset.raidEdit};render();return}
  if(button.dataset.raidStep){const raid=state.raids.items[button.dataset.raidStep];raid.current=Math.min(raid.target,raid.current+(raid.id==='toa'?10:25));raid.status=raid.current>=raid.target?'done':'active';save('Progresso da raid atualizado');render();return}
  if(button.dataset.historyDelete){state.history=state.history.filter(item=>item.id!==button.dataset.historyDelete);save('Registro removido');render();return}
  if(button.matches('[data-export-history]')){download(JSON.stringify(state.history,null,2),'osrs-historico.json');return}
  if(button.dataset.musicPrev!==undefined){await selectMusic(ui.musicIndex-1);return}
  if(button.dataset.musicNext!==undefined){await selectMusic(ui.musicIndex+1);return}
  if(button.dataset.musicPick!==undefined){await selectMusic(Number(button.dataset.musicPick),true);return}
  if(button.dataset.musicToggle!==undefined){await toggleMusic();return}
  if(button.dataset.theme){state.preferences.background=button.dataset.theme;save('Tema aplicado');render();return}
  if(button.matches('[data-background-upload]')){chooseFile('image/*',async file=>{state.preferences.customBackground=await compressImage(file,1600,0.78);state.preferences.background='custom';save('Fundo personalizado aplicado');render()});return}
  if(button.matches('[data-background-remove]')){state.preferences.customBackground='';state.preferences.background='wallpaper';save('Fundo removido');render();return}
  if(button.matches('[data-export]')){activeProfile().state=state;download(JSON.stringify(profileHub,null,2),`osrs-personagens-${new Date().toISOString().slice(0,10)}.json`);return}
  if(button.matches('[data-import]')){chooseFile('.json',importBackup);return}
  if(button.matches('[data-reset]')){if(confirm('Reiniciar somente o personagem atual?')){const profile=activeProfile();state=presetState(profile.preset,profile.username,profile.name);save('Personagem reiniciado');navigate('dashboard')}return}
  if(button.matches('[data-undo]')){undo();return}
});

document.addEventListener('keydown',event=>{
  const form=event.target.closest?.('.drawer-form');
  if(!form)return;
  if(event.key==='Enter'&&!event.target.matches('textarea,button[data-drawer-save]'))event.preventDefault();
  if(event.key==='Escape'){event.preventDefault();ui.drawer=null;render()}
});

document.addEventListener('change',event=>{
  const input=event.target;
  if(input.name==='type'&&input.closest('[data-goal-form]')){const form=input.closest('[data-goal-form]');if(input.value==='quest')form.elements.mode.value='quest';else if(form.elements.mode.value==='quest')form.elements.mode.value='manual';return}
  if(input.dataset.taskCheck){const task=state.tasks.find(item=>item.id===input.dataset.taskCheck);task.done=input.checked;if(task.done)addHistory('session',task.text,'Ação da sessão concluída.');save(task.done?'Ação concluída':'Ação reaberta');render();return}
  if(input.dataset.bossSelect){const bossId=input.dataset.bossSelect;if(input.checked&&!state.bosses.selected.includes(bossId))state.bosses.selected.push(bossId);if(!input.checked)state.bosses.selected=state.bosses.selected.filter(item=>item!==bossId);input.closest('.catalog-item')?.classList.toggle('selected',input.checked);save('Seleção atualizada',true);if(input.checked)loadBossImages();return}
  if(input.dataset.raidSelect){const raidId=input.dataset.raidSelect;if(input.checked&&!state.raids.selected.includes(raidId))state.raids.selected.push(raidId);if(!input.checked)state.raids.selected=state.raids.selected.filter(item=>item!==raidId);save('Raids atualizadas',true);return}
  if(input.dataset.widgetVisible){const key=input.dataset.widgetVisible;if(input.checked)state.dashboard.hidden=state.dashboard.hidden.filter(item=>item!==key);else if(!state.dashboard.hidden.includes(key))state.dashboard.hidden.push(key);save('Widgets atualizados');return}
  if(input.matches('[data-goal-filter]')){ui.goalFilter=input.value;render();return}
  if(input.matches('[data-quest-filter]')){ui.questFilter=input.value;render();return}
  if(input.matches('[data-boss-category]')){ui.bossCategory=input.value;render();return}
  if(input.matches('[data-history-filter]')){ui.historyFilter=input.value;render();return}
});
document.addEventListener('input',event=>{
  if(event.target.matches('[data-goal-search]')){ui.goalSearch=event.target.value;clearTimeout(ui.searchTimer);ui.searchTimer=setTimeout(render,120)}
  if(event.target.matches('[data-quest-search]')){ui.questSearch=event.target.value;clearTimeout(ui.questTimer);ui.questTimer=setTimeout(render,120)}
  if(event.target.matches('[data-boss-search]')){ui.bossSearch=event.target.value;clearTimeout(ui.bossTimer);ui.bossTimer=setTimeout(render,120)}
  if(event.target.name==='cardOpacity')event.target.closest('label').querySelector('output').textContent=`${event.target.value}%`;
  if(event.target.matches('[data-music-volume]')){state.preferences.musicVolume=Number(event.target.value);const audio=musicAudio();if(audio)audio.volume=state.preferences.musicVolume/100;$$('[data-music-volume]').forEach(input=>{if(input!==event.target)input.value=state.preferences.musicVolume});$$('.music-settings-volume output').forEach(output=>output.textContent=`${state.preferences.musicVolume}%`);clearTimeout(ui.musicVolumeTimer);ui.musicVolumeTimer=setTimeout(()=>save('Volume atualizado',true),180)}
});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target;
  if(form.closest('.drawer')&&!event.submitter?.matches('[data-drawer-save]'))return;
  const data=new FormData(form);if(form.closest('.drawer')){delete ui.drawerDrafts[drawerKey()];ui.skipDrawerDraft=true}
  if(form.matches('[data-profile-form]')){const profileId=data.get('id'),name=data.get('name').trim(),username=data.get('username').trim(),accountType=data.get('accountType'),duplicate=profileHub.profiles.find(profile=>profile.id!==profileId&&profile.username.toLowerCase()===username.toLowerCase());if(duplicate){toast('Esse personagem já está cadastrado.');return}if(profileId){const profile=profileHub.profiles.find(item=>item.id===profileId),changedNick=profile.username.toLowerCase()!==username.toLowerCase();profile.name=name;profile.username=username;profile.accountType=accountType;const profileState=profile.id===profileHub.activeId?state:profile.state;profileState.account=name;profileState.username=username;if(changedNick){profileState.lastSync=null;profileState.quests={items:[],lastSync:null,source:''}}profile.state=profileState;persistProfiles();ui.drawer=null;save('Personagem atualizado');render()}else{const preset=data.get('preset')||'blank',profile={id:id('profile'),name,username,accountType,preset,createdAt:new Date().toISOString(),state:presetState(preset,username,name)};activeProfile().state=state;profileHub.profiles.push(profile);profileHub.activeId=profile.id;state=mergeDefaults(profile.state);persistProfiles();ui.drawer=null;navigate('dashboard');toast(`${name} criado`);await syncAccount();await syncQuests(true)}return}
  if(form.matches('[data-goal-form]')){const goalId=data.get('id'),mode=data.get('mode'),questName=data.get('questName')||null;if(mode==='quest'&&!questName){toast('Selecione a quest que será acompanhada.');return}let goal=goalId?goalById(goalId):null;const before=goal?.status;if(!goal){goal={id:id('goal'),priority:state.goals.length+1};state.goals.push(goal)}Object.assign(goal,{title:data.get('title').trim(),description:data.get('description').trim(),type:mode==='quest'?'quest':data.get('type'),status:data.get('status'),mode,eraId:data.get('eraId')||null,questName,skill:data.get('skill')||null,bossId:data.get('bossId')||null,raidId:data.get('raidId')||null,target:Number(data.get('target'))||100,progress:Number(data.get('progress'))||0});if(mode==='quest'&&Number(questByName(questName)?.state)===2)goal.status='done';if(goal.status==='done'&&before!=='done')addHistory('goal',`${goal.title} concluída`,'Meta finalizada.');save(goalId?'Meta atualizada':'Meta criada e vinculada ao Roadmap');ui.drawer=null;render();return}
  if(form.matches('[data-era-form]')){const eraId=data.get('id');let era=state.eras.find(item=>item.id===eraId);if(!era){era={id:id('era'),order:state.eras.length};state.eras.push(era)}era.title=data.get('title').trim();era.description=data.get('description').trim();save(eraId?'Capítulo atualizado':'Capítulo criado');ui.drawer=null;render();return}
  if(form.matches('[data-task-form]')){state.tasks.push({id:id('task'),text:data.get('text').trim(),done:false,goalId:data.get('goalId')||null});save('Ação adicionada');render();return}
  if(form.matches('[data-task-edit-form]')){const task=state.tasks.find(item=>item.id===data.get('id'));task.text=data.get('text').trim();task.goalId=data.get('goalId')||null;save('Ação atualizada');ui.drawer=null;render();return}
  if(form.matches('[data-session-log]')){addHistory('session',data.get('title').trim(),`${data.get('result')} · ${data.get('detail').trim()}`);save('Sessão registrada');form.reset();render();return}
  if(form.matches('[data-focus-form]')){state.dashboard.focus=data.getAll('focus').filter(Boolean).slice(0,3);save('Home personalizada');ui.drawer=null;render();return}
  if(form.matches('[data-boss-form]')){const bossId=data.get('id'),progress=bossProgress(bossId),previous=progress.kc;Object.assign(progress,{kc:Number(data.get('kc'))||0,target:Number(data.get('target'))||25,status:data.get('status'),best:data.get('best'),gear:data.get('gear'),notes:data.get('notes'),project:data.get('project')==='on'});const file=form.elements.image.files[0];if(file)progress.image=await compressImage(file,512,0.82);if(progress.kc>previous)addHistory('pvm',`${state.bosses.catalog.find(item=>item.id===bossId).name}: ${progress.kc} KC`,`Avanço de ${progress.kc-previous} KC.`);save('Boss atualizado');ui.drawer=null;render();return}
  if(form.matches('[data-raid-form]')){const raid=state.raids.items[data.get('id')],previous=raid.current;Object.assign(raid,{mode:data.get('mode'),current:Number(data.get('current'))||0,target:Number(data.get('target'))||100,status:data.get('status'),best:data.get('best'),notes:data.get('notes')});if(raid.current>previous)addHistory('pvm',`${raid.name}: ${raid.current}`,`${raid.mode} atualizado.`);save('Raid atualizada');ui.drawer=null;render();return}
  if(form.matches('[data-custom-boss]')){const name=data.get('name').trim(),bossId=`custom-${slug(name)}-${Date.now().toString(36)}`;state.bosses.catalog.push({id:bossId,name,category:data.get('category').trim()||'Personalizado',wiki:name});state.bosses.selected.push(bossId);bossProgress(bossId);save('Conteúdo adicionado');render();return}
  if(form.matches('[data-preferences]')){state.preferences.accent=data.get('accent');state.preferences.cardOpacity=Number(data.get('cardOpacity'));state.preferences.density=data.get('density');state.preferences.motion=data.get('motion')==='on';state.preferences.startPage=data.get('startPage');save('Aparência atualizada');render();return}
  if(form.matches('[data-sync-form]')){const username=data.get('username').trim();if(username.toLowerCase()!==state.username.toLowerCase()){state.username=username;state.lastSync=null;state.quests={items:[],lastSync:null,source:''}}save('Nick atualizado',true);await syncAccount();return}
  if(form.matches('[data-account-form]')){state.account=data.get('account').trim()||'Minha conta';state.totalGoal=Number(data.get('totalGoal'))||2000;save('Identidade atualizada');render();return}
});

function chooseFile(accept,callback){const bridge=$('#fileBridge');bridge.accept=accept;bridge.value='';bridge.onchange=()=>{if(bridge.files[0])callback(bridge.files[0])};bridge.click()}
function download(content,name){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([content],{type:'application/json'}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500)}
function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const incoming=JSON.parse(reader.result);if(incoming.version===1&&Array.isArray(incoming.profiles)&&incoming.profiles.length){if(confirm('Substituir todos os personagens por este backup?')){profileHub=incoming;profileHub.profiles.forEach(profile=>profile.state=mergeDefaults(profile.state));if(!profileHub.profiles.some(profile=>profile.id===profileHub.activeId))profileHub.activeId=profileHub.profiles[0].id;state=mergeDefaults(activeProfile().state);persistProfiles();toast('Todos os personagens foram restaurados');navigate('profiles')}}else if(incoming.version===3){if(confirm('Substituir somente o personagem atual por este backup antigo?')){state=mergeDefaults(incoming);save('Personagem restaurado');navigate('dashboard')}}else throw new Error()}catch{toast('Este arquivo não é um backup válido')}};reader.readAsText(file)}
function compressImage(file,maxSize=1200,quality=.8){return new Promise((resolve,reject)=>{const image=new Image(),reader=new FileReader();reader.onload=()=>image.src=reader.result;reader.onerror=reject;image.onload=()=>{const scale=Math.min(1,maxSize/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/webp',quality))};reader.readAsDataURL(file)})}

async function syncAccount(){const buttons=$$('[data-sync], [data-sync-form] button');buttons.forEach(button=>{button.disabled=true;button.textContent='↻ Atualizando...'});try{await fetch(`https://api.wiseoldman.net/v2/players/${encodeURIComponent(state.username)}`,{method:'POST',headers:{'Content-Type':'application/json'}});const response=await fetch(`https://api.wiseoldman.net/v2/players/${encodeURIComponent(state.username)}`);if(!response.ok)throw new Error('Conta não encontrada');const payload=await response.json(),snapshot=payload.latestSnapshot?.data,womType=({regular:'main',ironman:'ironman',hardcore:'hardcore',ultimate:'ultimate'})[payload.type];if(womType)activeProfile().accountType=womType;if(!snapshot)throw new Error('Sem snapshot disponível');const map={attack:'Attack',strength:'Strength',defence:'Defence',hitpoints:'Hitpoints',ranged:'Ranged',prayer:'Prayer',magic:'Magic',cooking:'Cooking',woodcutting:'Woodcutting',fletching:'Fletching',fishing:'Fishing',firemaking:'Firemaking',crafting:'Crafting',smithing:'Smithing',mining:'Mining',herblore:'Herblore',agility:'Agility',thieving:'Thieving',slayer:'Slayer',farming:'Farming',runecrafting:'Runecraft',hunter:'Hunter',construction:'Construction',sailing:'Sailing'};const gained=[];Object.entries(map).forEach(([key,name])=>{const item=skill(name),level=snapshot.skills?.[key]?.level;if(item&&Number.isFinite(level)&&level>0){if(level>item.current)gained.push(`${name} ${item.current}→${level}`);item.current=level;item.xp=snapshot.skills[key].experience||item.xp}});if(state.profileSetupPending){state.skills.forEach(item=>{if(item.target<=item.current)item.target=item.current>=99?99:Math.min(99,Math.ceil((item.current+3)/5)*5)});state.profileSetupPending=false}if(snapshot.skills?.overall?.level)state.total=snapshot.skills.overall.level;const bossMetrics=snapshot.bosses||{};state.bosses.catalog.forEach(item=>{const metric=Object.entries(bossMetrics).find(([key])=>slug(key)===slug(item.name));const kc=metric?.[1]?.kills;if(Number.isFinite(kc)&&kc>=0)bossProgress(item.id).kc=kc});state.lastSync=new Date().toISOString();addHistory('sync','Conta sincronizada',gained.length?gained.join(', '):'Níveis e KCs conferidos.');save('Conta atualizada');render()}catch(error){toast(`Não foi possível atualizar: ${error.message}`);buttons.forEach(button=>button.disabled=false)}}

async function syncQuests(silent=false){
  if(ui.questSyncing)return;
  ui.questSyncing=true;
  if(route==='quests')render();
  try{
    let response,source='WikiSync ao vivo';
    try{response=await fetch(`https://sync.runescape.wiki/runelite/player/${encodeURIComponent(state.username)}/STANDARD`);if(!response.ok)throw new Error()}catch{const snapshot=slug(state.username)==='samurai-jao'?'quest-data.json':`quest-data-${slug(state.username)}.json`;response=await fetch(`${snapshot}?v=${Date.now()}`);source='Snapshot automático do GitHub'}
    if(!response.ok)throw new Error('perfil ainda não disponível no WikiSync');
    const payload=await response.json();
    if(source!=='WikiSync ao vivo'&&String(payload.username).toLowerCase()!==String(state.username).toLowerCase())throw new Error('o snapshot pertence a outro personagem');
    const entries=Object.entries(payload.quests||{}).filter(([name])=>name!=='.');
    if(!entries.length)throw new Error('nenhuma quest encontrada');
    state.quests.items=entries.map(([name,value])=>({name,state:Number(value)}));
    state.quests.lastSync=payload.timestamp||new Date().toISOString();
    state.quests.source=source;
    const completed=[];
    state.goals.filter(goal=>goal.mode==='quest'&&goal.status!=='archived').forEach(goal=>{const quest=questByName(goal.questName);if(!quest)return;if(Number(quest.state)===2&&goal.status!=='done'){goal.status='done';completed.push(goal.title);addHistory('goal',`${goal.title} concluída`,'Conclusão detectada automaticamente pelo WikiSync.')}else if(Number(quest.state)===1&&goal.status==='planned')goal.status='active'});
    save(silent?'Quests sincronizadas':completed.length?`${completed.length} meta(s) de quest concluída(s)`:'Quests atualizadas',silent);
  }catch(error){if(!silent)toast(`Não foi possível atualizar as quests: ${error.message}`)}finally{ui.questSyncing=false;render()}
}

async function loadWikiCatalog(){if(state.bosses.wikiLoaded)return;try{const response=await fetch('https://oldschool.runescape.wiki/api.php?action=query&format=json&origin=*&list=categorymembers&cmtitle=Category%3ABosses&cmlimit=max&cmtype=page');const payload=await response.json(),known=new Set(state.bosses.catalog.map(item=>item.wiki));(payload.query?.categorymembers||[]).forEach(entry=>{if(!known.has(entry.title)){state.bosses.catalog.push({id:`wiki-${entry.pageid}`,name:entry.title,category:'Catálogo Wiki',wiki:entry.title});known.add(entry.title)}});state.bosses.wikiLoaded=true;save('Catálogo atualizado',true)}catch{}}
async function loadBossImages(){const missing=state.bosses.selected.map(bossId=>state.bosses.catalog.find(item=>item.id===bossId)).filter(item=>item&&!item.image).slice(0,45);if(!missing.length)return;try{const titles=missing.map(item=>item.wiki||item.name).join('|'),response=await fetch(`https://oldschool.runescape.wiki/api.php?action=query&format=json&origin=*&prop=pageimages&piprop=original&titles=${encodeURIComponent(titles)}`),payload=await response.json();Object.values(payload.query?.pages||{}).forEach(page=>{const item=missing.find(entry=>(entry.wiki||entry.name)===page.title);if(item&&page.original?.source)item.image=page.original.source});save('Imagens atualizadas',true);if(route==='pvm'&&!ui.drawer)render()}catch{}}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next===route)return;if(titles[next]){route=next;ui.drawer=null;ui.menu=false;ui.routeEntering=true;window.scrollTo(0,0);render()}});
const osrsPlayer=musicAudio();
osrsPlayer.addEventListener('play',()=>{ui.musicPlaying=true;updateMusicUI()});
osrsPlayer.addEventListener('pause',()=>{ui.musicPlaying=false;updateMusicUI()});
osrsPlayer.addEventListener('ended',()=>selectMusic(ui.musicIndex+1,true));
osrsPlayer.addEventListener('error',()=>{ui.musicPlaying=false;updateMusicUI();toast('Não foi possível carregar esta faixa.')});
loadWikiCatalog().then(loadBossImages);save('Pronto',true);render();syncQuests(true);
